using File=CodexKit.Native.NativeFile;
using Directory=CodexKit.Native.NativeDirectory;
using FileInfo=CodexKit.Native.NativeFileInfo;
using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Diagnostics;
namespace CodexKit.Native {
public static class NativeCli {
    public static int Run(string[] args,string entryPrefix=""){NativeRuntime.Configure();var encoding=new UTF8Encoding(false);try{Console.OutputEncoding=encoding;}catch(IOException){Console.SetOut(new StreamWriter(Console.OpenStandardOutput(),encoding){AutoFlush=true});Console.SetError(new StreamWriter(Console.OpenStandardError(),encoding){AutoFlush=true});}try{
        if(args.Length==0)return Menu(entryPrefix);if(args[0]=="--version"||args[0]=="version"){Console.WriteLine("Codex Init Kit Native CLI "+NativeData.Version);return 0;}
        if(args[0]=="--help"||args[0]=="help"){Help();return 0;}
        string command=args[0];var values=Parse(args.Skip(1).ToArray());
        if(command=="--apply-update"){return NativeUpdater.Complete(Need(values,"plan"),Int32.Parse(Need(values,"parent-pid")),Int64.Parse(Need(values,"parent-start")));}
        var paths=NativePaths.Current();paths.EntryPrefix=entryPrefix;string value;if(values.TryGetValue("home",out value))paths.Home=Path.GetFullPath(value);if(values.TryGetValue("workspace",out value))paths.Workspace=Path.GetFullPath(value);if(values.TryGetValue("drive",out value)){if(value.Length!=1||!Char.IsLetter(value[0]))throw new ArgumentException("工作盘请填写一个字母。");paths.Workspace=value.ToUpperInvariant()+":\\Codex";}
        var options=new NativeOptions();options.Confirm=values.ContainsKey("confirm");options.AllowClose=values.ContainsKey("allow-close");options.Proxy=!values.ContainsKey("no-proxy");options.Folder=!values.ContainsKey("no-folder");options.Subagents=!values.ContainsKey("no-subagents");options.Cua=!values.ContainsKey("no-cua");if(values.TryGetValue("proxy-port",out value))options.ProxyPort=Int32.Parse(value);else if(options.Proxy)options.ProxyPort=ProxyPortSettings.Load(paths.Home);
        if(values.TryGetValue("proxy-host",out value))options.ProxyHost=value;if(values.TryGetValue("parent-model",out value))options.ParentModel=value;if(values.TryGetValue("parent-effort",out value))options.ParentEffort=value;if(values.TryGetValue("child-model",out value))options.ChildModel=value;if(values.TryGetValue("child-effort",out value))options.ChildEffort=value;
        var services=Services(paths,options);var engine=new NativeInitializer(paths,services);
        if(command=="status"){Console.WriteLine(NativeData.Json.Serialize(engine.Status()));return 0;}
        if(command=="preflight"){Console.WriteLine(NativeData.Json.Serialize(engine.Preflight()));return 0;}
        if(command=="check-update"||command=="update"){
            if(command=="update"&&!String.IsNullOrEmpty(entryPrefix))throw new InvalidOperationException("桌面 EXE 请使用桌面更新入口；原生命令不会用 CLI 组件覆盖桌面程序。");var updater=new NativeUpdater(services.Downloads);var remote=updater.Check();Console.WriteLine(NativeData.Json.Serialize(remote));if(command=="check-update"||!options.Confirm){if(command=="update")Console.WriteLine("尚未确认，未下载或替换程序。");return 0;}
            var updaterPath=NativeUpdater.HelperPath(paths.Self);var plan=updater.Prepare(remote,paths.Self,NativeData.Version);using(var self=Process.GetCurrentProcess()){var info=new ProcessStartInfo(updaterPath,"--apply-update --plan "+NativeData.Quoted(plan.stage+".json")+" --parent-pid "+self.Id+" --parent-start "+self.StartTime.ToUniversalTime().Ticks){UseShellExecute=false,CreateNoWindow=true};using(var worker=Process.Start(info)){if(worker==null)throw new IOException("原生更新进程未启动。");}}Console.WriteLine("已准备并校验更新，当前 CLI 退出后由原生进程替换；未调用 PowerShell。");return 20;
        }
        if(command=="cua-check"||command=="cua-repair"){
            if(command=="cua-repair"&&!options.Confirm){Console.WriteLine("未确认，不修改 CUA。");return 2;}if(command=="cua-repair")AuthorizeExisting(paths,services,options);var report=Path.Combine(paths.BackupRoot,"CUA_"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));if(command=="cua-repair")NativeProcessWorkflow.EnsureStopped(paths,services.Desktop.Discover(),services.Processes,options.AllowClose,options.ApprovedProcesses,services.Log);var result=new NativeCua(paths,services).Run(command=="cua-repair",report);Console.WriteLine(NativeData.Json.Serialize(result));return result.Passed?0:3;
        }
        if(!new[]{"init","reset","proxy","rollback"}.Contains(command))throw new ArgumentException("未知命令；使用 --help 查看。");
        if(options.Confirm&&options.AllowClose)AuthorizeExisting(paths,services,options);
        string session;values.TryGetValue("session",out session);var init=engine.Run(command,options,session,preserveCli:command!="init"&&!String.IsNullOrEmpty(entryPrefix));Console.WriteLine(NativeData.Json.Serialize(init));return init.ExitCode;
    }catch(Exception ex){var cause=ex;while(cause.InnerException!=null)cause=cause.InnerException;Console.Error.WriteLine("操作未完成："+ex.GetType().Name+"："+ex.Message+(Object.ReferenceEquals(cause,ex)?"":"；具体原因："+cause.GetType().Name+"："+cause.Message));return 1;}}
    static void AuthorizeExisting(NativePaths paths,NativeServices services,NativeOptions options){if(!options.AllowClose)return;OfficialDesktop app;try{app=services.Desktop.Discover();}catch(FileNotFoundException){app=null;}options.ApprovedProcesses=services.Processes.List(paths,app).Select(p=>p.Key).ToArray();}
    public static NativeServices Services(NativePaths paths,NativeOptions options){var networkPath=Path.Combine(paths.LocalData,"CodexInitKit","Desktop","network.json");return new NativeServices{Registry=new WindowsRegistryStore(),Commands=new NativeCommandRunner(),Downloads=new NativeGitHubDownloads(GitHubNetworkOptions.Load(networkPath),options.Proxy?options.ProxyPort:0,options.ProxyHost,Console.WriteLine),Desktop=new WindowsNativeDesktop(),Processes=new WindowsNativeProcesses(),Log=Console.WriteLine};}
    static Dictionary<string,string> Parse(string[] args){var options=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);var switches=new HashSet<string>(new[]{"confirm","allow-close","no-proxy","no-folder","no-subagents","no-cua"});var names=new HashSet<string>(new[]{"home","workspace","drive","proxy-port","proxy-host","parent-model","parent-effort","child-model","child-effort","session","plan","parent-pid","parent-start"});for(int i=0;i<args.Length;i++){if(!args[i].StartsWith("--"))throw new ArgumentException("参数须以 -- 开头。");var key=args[i].Substring(2);if(options.ContainsKey(key))throw new ArgumentException("参数重复："+key);if(switches.Contains(key))options[key]="true";else{if(!names.Contains(key)||i+1==args.Length)throw new ArgumentException("参数未知或缺少值："+key);options[key]=args[++i];}}return options;}
    static string Need(Dictionary<string,string> values,string key){string value;if(!values.TryGetValue(key,out value))throw new ArgumentException("缺少参数：--"+key);return value;}
    static void Help(){Console.WriteLine("Codex Init Kit 原生初始化 CLI（本地迁移版）\n\nstatus / preflight：只读检查\ninit --drive D --confirm：一键初始化\nreset --confirm：只重建基础配置、代理和规则\nproxy --proxy-port 3067 --confirm：只重建代理\nrollback [--session 备份目录] --confirm：指定或最近回滚\ncua-check / cua-repair --confirm：组件检查／修复\ncheck-update / update --confirm：原生 CLI 更新\n\n可选：--workspace 绝对目录、--home CODEX_HOME、--proxy-host IP、--no-proxy、--no-folder、--no-subagents、--no-cua、父子模型与思考强度。\n仅显式添加 --allow-close 才授权关闭本次识别的当前用户应用；会中断任务，请先保存。\n默认模型与旧独立脚本一致：gpt-6.1-sol / 高（high）。不指定命令时进入中文菜单。");}
    static int Menu(string entryPrefix){while(true){Console.WriteLine("\nCodex 原生初始化与维护\n1 一键初始化\n2 状态与诊断\n3 仅重建代理\n4 回滚最近初始化\n5 检查原生 CLI 更新\n0 退出\n请选择：");var input=Console.ReadLine();if(input==null||input=="0")return 0;if(input=="2"){Run(new[]{"status"},entryPrefix);continue;}if(input=="5"){if(Run(new[]{"check-update"},entryPrefix)==0){Console.WriteLine("如有新版本，是否确认下载并更新原生 CLI？[y/N]");if(String.Equals(Console.ReadLine(),"y",StringComparison.OrdinalIgnoreCase)&&Run(new[]{"update","--confirm"},entryPrefix)==20)return 0;}continue;}string action=input=="1"?"init":input=="3"?"proxy":input=="4"?"rollback":null;if(action==null)continue;var arguments=new List<string>{action};if(action=="init"){Console.WriteLine("工作盘字母（如 D）：");var drive=Console.ReadLine();arguments.AddRange(new[]{"--drive",drive??""});}Console.WriteLine("操作会备份并修改所选配置。确认继续？[y/N]");if(!String.Equals(Console.ReadLine(),"y",StringComparison.OrdinalIgnoreCase))continue;arguments.Add("--confirm");Console.WriteLine("如检测到 ChatGPT／Codex，是否允许关闭本次识别的相关进程？任务会中断，请先保存。[y/N]");if(String.Equals(Console.ReadLine(),"y",StringComparison.OrdinalIgnoreCase))arguments.Add("--allow-close");Run(arguments.ToArray(),entryPrefix);}}
}
}
